const items = $input.all();
// ── Source health: classify every raw payload before normalizing ────────
const __srcStats = { ok: {}, bad: [] };
for (const __it of items) {
  const __d = __it.json;
  if (!__d || typeof __d !== 'object') continue;
  if (__d.message && Object.keys(__d).length === 1) {
    __srcStats.bad.push('API error: ' + String(__d.message).substring(0, 90));
  } else if (typeof __d.data === 'string' && __d.data.trim().startsWith('<')) {
    __srcStats.bad.push('HTML error page instead of JSON');
  } else if (Array.isArray(__d.results) && __d.results.length === 0) {
    __srcStats.bad.push('query returned 0 results');
  }
}

let allJobs = [];

for (const item of items) {
  const d = item.json;

  // ── JSearch (object with d.data array) ───────────────────────────────────
  if (d.data && (Array.isArray(d.data) || Array.isArray(d.data.jobs))) {
    const _jsJobs = Array.isArray(d.data) ? d.data : d.data.jobs;
    for (const j of _jsJobs) {
      allJobs.push({
        job_id:      'jsearch_' + j.job_id,
        title:       j.job_title || '',
        company:     j.employer_name || '',
        location:    j.job_is_remote ? 'Remote' : `${j.job_city||''} ${j.job_state||''} ${j.job_country||''}`.trim(),
        is_remote:   j.job_is_remote === true,
        apply_url:   j.job_apply_link || '',
        description: (j.job_description || '').substring(0, 3000),
        salary_min:  j.job_min_salary || null,
        salary_max:  j.job_max_salary || null,
        salary_text: '',
        posted_date: j.job_posted_at_timestamp
          ? new Date(j.job_posted_at_timestamp * 1000).toISOString().split('T')[0] : '',
        source: 'JSearch'
      });
    }
  }

  // ── Adzuna (results array + count number) ────────────────────────────────
  else if (d.results && Array.isArray(d.results) && typeof d.count === 'number') {
    for (const j of d.results) {
      allJobs.push({
        job_id:      'adzuna_' + (j.id || Math.random().toString(36).substr(2,9)),
        title:       j.title || '',
        company:     (j.company && j.company.display_name) || '',
        location:    (j.location && j.location.display_name) || '',
        is_remote:   ((j.title||'') + ' ' + (j.description||'')).toLowerCase().includes('remote'),
        apply_url:   j.redirect_url || '',
        description: (j.description || '').substring(0, 3000),
        salary_min:  j.salary_min || null,
        salary_max:  j.salary_max || null,
        salary_text: '',
        posted_date: j.created ? j.created.split('T')[0] : '',
        source: 'Adzuna'
      });
    }
  }

  // ── The Muse (results array + page number) ───────────────────────────────
  else if (d.results && Array.isArray(d.results) && typeof d.page === 'number') {
    for (const j of d.results) {
      if (!j.name) continue;
      allJobs.push({
        job_id:      'muse_' + (j.id || Math.random().toString(36).substr(2,9)),
        title:       j.name || '',
        company:     (j.company && j.company.name) || '',
        location:    'Remote',
        is_remote:   true,
        apply_url:   (j.refs && j.refs.landing_page) || '',
        description: (j.contents || '').replace(/<[^>]*>/g, '').substring(0, 3000),
        salary_min:  null,
        salary_max:  null,
        salary_text: '',
        posted_date: j.publication_date ? j.publication_date.split('T')[0] : '',
        source: 'TheMuse'
      });
    }
  }

  // ── Remotive (jobs array) ─────────────────────────────────────────────────
  else if (d.jobs && Array.isArray(d.jobs)) {
    for (const j of d.jobs) {
      allJobs.push({
        job_id:      'remotive_' + (j.id || Math.random().toString(36).substr(2,9)),
        title:       j.title || '',
        company:     j.company_name || '',
        location:    j.candidate_required_location || 'Remote',
        is_remote:   true,
        apply_url:   j.url || '',
        description: (j.description || '').replace(/<[^>]*>/g, '').substring(0, 3000),
        salary_min:  null,
        salary_max:  null,
        salary_text: j.salary || '',
        posted_date: j.publication_date ? j.publication_date.split('T')[0] : '',
        source: 'Remotive'
      });
    }
  }

  // ── Indeed via RapidAPI (hits array) ─────────────────────────────────────
  else if (d.hits && Array.isArray(d.hits)) {
    for (const j of d.hits) {
      allJobs.push({
        job_id:      'indeed_' + (j.id || Math.random().toString(36).substr(2,9)),
        title:       j.title || '',
        company:     j.company || '',
        location:    (j.location||'').toLowerCase().includes('remote') ? 'Remote' : (j.location || ''),
        is_remote:   (j.location||'').toLowerCase().includes('remote')
                  || ((j.title||'') + ' ' + (j.description||j.summary||'')).toLowerCase().includes('remote'),
        apply_url:   j.url || j.link || '',
        description: (j.description || j.summary || j.snippet || '').substring(0, 3000),
        salary_min:  null,
        salary_max:  null,
        salary_text: j.salary || '',
        posted_date: j.date || j.datePosted || '',
        source: 'Indeed'
      });
    }
  }



  // ── LinkedIn Job Search API (active-jb-24h) — array of rich objects ───────
  else if (Array.isArray(d) && d.length > 0 && d[0].date_posted !== undefined && d[0].organization !== undefined) {
    for (const j of d) {
      if (!j.title) continue;

      // Build location string
      const locs = j.locations_derived || [];
      const locStr = locs.length > 0 ? locs[0] : '';

      // Remote detection: remote_derived flag, location_type TELECOMMUTE, or "remote" in loc/description
      const descLower = (j.description_text || '').toLowerCase().substring(0, 500);
      const isRemote = j.remote_derived === true
        || j.location_type === 'TELECOMMUTE'
        || locStr.toLowerCase().includes('remote')
        || descLower.includes('remote');

      // Salary: salary_raw is a structured object {value: [{value, unitText, currency, ...}]}
      let salMin = null, salMax = null, salText = '';
      if (j.salary_raw && j.salary_raw.value) {
        const vals = j.salary_raw.value;
        if (vals.length === 1) {
          salMin = vals[0].value || null;
          salText = vals[0].currency ? `${vals[0].currency} ${vals[0].value}` : String(vals[0].value || '');
        } else if (vals.length >= 2) {
          salMin = Math.min(...vals.map(v => v.value || 0).filter(v => v > 0)) || null;
          salMax = Math.max(...vals.map(v => v.value || 0)) || null;
        }
      }

      allJobs.push({
        job_id:      'linkedin_' + (j.id || Math.random().toString(36).substr(2, 9)),
        title:       j.title || '',
        company:     j.organization || '',
        location:    isRemote ? 'Remote' : locStr,
        is_remote:   isRemote,
        apply_url:   j.external_apply_url || j.url || '',
        description: (j.description_text || '').substring(0, 3000),
        salary_min:  salMin,
        salary_max:  salMax,
        salary_text: salText,
        posted_date: j.date_posted ? j.date_posted.split('T')[0] : '',
        source: 'LinkedIn'
      });
    }
  }


  // ── LinkedIn individual job object (n8n splits array → one item per job) ──
  else if (d.linkedin_id !== undefined && d.organization !== undefined && d.title) {
    const locs = d.locations_derived || [];
    const locStr = locs.length > 0 ? locs[0] : '';
    const descLower = (d.description_text || '').toLowerCase().substring(0, 500);
    const isRemote = d.remote_derived === true
      || d.location_type === 'TELECOMMUTE'
      || locStr.toLowerCase().includes('remote')
      || descLower.includes('remote');

    let salMin = null, salMax = null, salText = '';
    if (d.salary_raw && d.salary_raw.value) {
      const vals = d.salary_raw.value;
      if (vals.length === 1) {
        salMin = vals[0].value || null;
        salText = vals[0].currency ? `${vals[0].currency} ${vals[0].value}` : String(vals[0].value || '');
      } else if (vals.length >= 2) {
        salMin = Math.min(...vals.map(v => v.value || 0).filter(v => v > 0)) || null;
        salMax = Math.max(...vals.map(v => v.value || 0)) || null;
      }
    }

    allJobs.push({
      job_id:      'linkedin_' + d.id,
      title:       d.title || '',
      company:     d.organization || '',
      location:    isRemote ? 'Remote' : locStr,
      is_remote:   isRemote,
      apply_url:   d.external_apply_url || d.url || '',
      description: (d.description_text || '').substring(0, 3000),
      salary_min:  salMin,
      salary_max:  salMax,
      salary_text: salText,
      posted_date: d.date_posted ? d.date_posted.split('T')[0] : '',
      source: 'LinkedIn'
    });
  }

  // ── Remote OK (top-level array, element 0 is legal notice) ───────────────
  // ── Remote OK (individual job objects — n8n split the array) ─────────────
  else if (d.position !== undefined && d.company !== undefined) {
    allJobs.push({
      job_id:      'remoteok_' + (d.id || Math.random().toString(36).substr(2,9)),
      title:       d.position || '',
      company:     d.company || '',
      location:    'Remote',
      is_remote:   true,
      apply_url:   d.apply_url || d.url || '',
      description: (d.description || '').replace(/<[^>]*>/g, '').substring(0, 3000),
      salary_min:  d.salary_min ? parseInt(d.salary_min) : null,
      salary_max:  d.salary_max ? parseInt(d.salary_max) : null,
      salary_text: '',
      posted_date: d.date ? d.date.split('T')[0] : '',
      source: 'RemoteOK'
    });
  }

  else if (Array.isArray(d)) {
    for (const j of d.slice(1)) {
      if (!j || !j.position) continue;
      allJobs.push({
        job_id:      'remoteok_' + (j.id || Math.random().toString(36).substr(2,9)),
        title:       j.position || '',
        company:     j.company || '',
        location:    'Remote',
        is_remote:   true,
        apply_url:   j.apply_url || j.url || '',
        description: (j.description || '').replace(/<[^>]*>/g, '').substring(0, 3000),
        salary_min:  j.salary_min ? parseInt(j.salary_min) : null,
        salary_max:  j.salary_max ? parseInt(j.salary_max) : null,
        salary_text: '',
        posted_date: j.date ? j.date.split('T')[0] : '',
        source: 'RemoteOK'
      });
    }
  }
}

// Remote, or in an allowed WA metro (hybrid/onsite is fine there). The state
// check keeps Nearby City C MS / Nearby City B TX etc. out. Remote-Only City is REMOTE ONLY
// (2026-10-04), so it is not an onsite metro.
// JSearch labels Washington D.C. jobs "Nearby City B, Washington" - 7 of 10 results on
// one query, 2026-10-04 - so an onsite "WA" job that talks about D.C. is not local.
const WA_OK = ['your city', 'nearby city a', 'nearby city b', 'nearby city c', 'metro area',
               'metro area'];
const DC_HINT = /washington,?\s*d\.?\s*c\b|\bd\.c\.|\bdc metro|\bdmv area\b/i;
const inWaMetro = j => {
  const l = (j.location || '').toLowerCase();
  if (!(WA_OK.some(k => l.includes(k)) && /washington|\bwa\b/.test(l))) return false;
  return !DC_HINT.test(j.title + ' ' + (j.description || '').substring(0, 2500));
};
allJobs = allJobs.filter(j =>
  j.is_remote || j.location.toLowerCase().includes('remote') || inWaMetro(j)
);

// ── Hard exclusions (title-based) — drop obvious software/web dev roles ───────
const DEV_TITLES = [
  'software engineer','software developer','software development',
  'web developer','web engineer','frontend','front-end','back-end','backend',
  'full stack','fullstack','full-stack',
  'mobile developer','ios developer','android developer',
  'data engineer','data scientist','ml engineer','machine learning',
  'application developer','application engineer',
  'java developer','python developer','ruby developer','rails developer',
  'react engineer','angular engineer','ui engineer','ux engineer',
  'staff engineer','principal software',
];
allJobs = allJobs.filter(j => {
  const title = j.title.toLowerCase();
  return !DEV_TITLES.some(kw => title.includes(kw));
});

// ── SRE / DevOps are out of scope (2026-10-01) - he does not qualify ───────
// "Network Reliability Engineer" is network work and stays; any other
// "reliability" title (Platform Reliability, Site Reliability) is SRE.
allJobs = allJobs.filter(j => {
  const t = j.title.toLowerCase();
  if (/\bsre\b|site reliability|\bdevops\b|\bdev ops\b/.test(t)) return false;
  if (t.includes('reliability') && !t.includes('network reliability')) return false;
  return true;
});

// ── Title must signal infra/ops/network/reliability — not generic "engineer" ─
const TITLE_OK = [
  'network reliability','firewall engineer','network automation',
  'network engineer','network architect','network administrator','network operations',
  'infrastructure engineer','infrastructure architect',
  'platform engineer','hybrid cloud engineer','hybrid cloud','cloud engineer','cloud network',
  'systems engineer','systems administrator','sysadmin',
  'noc engineer','network security engineer','infrastructure security',
  'cloud security engineer','firewall',
  'it engineer','it infrastructure','senior engineer',
  'security operations','operations engineer','cloud operations',
  'monitoring engineer','observability engineer','monitoring administrator',
  'infrastructure operations',
  'virtualization engineer','vmware engineer','server engineer','server administrator',
  'data center engineer','wireless engineer',
  'network operations center','network analyst','network specialist',
];
allJobs = allJobs.filter(j => {
  const title = j.title.toLowerCase();
  return TITLE_OK.some(kw => title.includes(kw));
});

// ── Exclusion keywords (security/legal) ───────────────────────────────────────
const EXCL = [
  'clearance required','requires clearance','must have clearance','active secret',
  'top secret','ts/sci','secret clearance','drug test','drug screen',
  'pre-employment drug','drug free workplace required'
];
allJobs = allJobs.filter(j => {
  const txt = (j.title + ' ' + j.description + ' ' + j.company).toLowerCase();
  return !EXCL.some(kw => txt.includes(kw));
});

// ── No clearance, no federal / federal-contractor work (2026-10-04) ─────────
// State and local government (City of Nearby City A, WA state agencies) are fine.
// A clearance in the TITLE is always out; in the body only the "must hold or
// obtain" phrasings count, so "no clearance required" does not trip it.
// Whole-word match (plural allowed), so 'saic' does not hit Mosaic and 'java'
// not JavaScript, but 'firewall' still counts 'firewalls'.
const kwHit = (txt, k) => new RegExp('(^|[^a-z0-9])' + k.replace(/[.*+?^${}()|[\]\\/]/g, '\\$&') + '(e?s)?([^a-z0-9]|$)').test(txt);
const CLEARANCE_BODY = [
  'security clearance is required','clearance is required','active clearance',
  'maintain a security clearance','maintain a clearance','obtain a security clearance',
  'eligible for a security clearance','public trust clearance','public trust position',
  'dod 8570','dod 8140','dod 8570.01','iat level ii','iat level iii',
];
const FED_EMPLOYERS = [
  'amentum','federal reserve','caci','saic','leidos',
  'mantech','peraton','gdit','general dynamics information','apogee','feditc',
  'federal it consulting','anduril','shield ai',
];
// Narrow on purpose: "As a federal contractor..." and "U.S. Department of Labor"
// sit in the EEO boilerplate of most large private employers.
const FED_BODY = [
  'department of energy','doe contract','national laboratory',
  'dod customer','support of the dod','support of dod','federal customer',
  'federal government client','federal agency client','supporting federal agencies',
];
allJobs = allJobs.filter(j => {
  const t = j.title.toLowerCase();
  const co = (j.company || '').toLowerCase();
  const body = (j.description || '').toLowerCase();
  let why = null;
  if (t.includes('clearance') || /\bts\/sci\b|\bsecret\b/.test(t)) why = 'clearance in title';
  else if (CLEARANCE_BODY.some(k => body.includes(k))) why = 'clearance required';
  else if (FED_EMPLOYERS.some(k => kwHit(co, k)
           || (k.length >= 6 && co.replace(/[^a-z0-9]/g, '').includes(k.replace(/[^a-z0-9]/g, '')))))
    why = 'federal/contractor employer';
  else if (FED_BODY.some(k => body.includes(k))) why = 'federal work';
  if (!why) return true;
  __srcStats.bad.push(`${why}: "${j.title}" (${j.company})`);
  return false;
});

// ── Salary: the posted band must reach $120k at EITHER end (2026-10-04) ────
// Unlisted pay is kept - most postings omit it - and left to the scorer.
const SAL_FLOOR = 120000;
const annual = v => {
  const n = Number(v);
  if (!n) return null;
  if (n < 1000) return n * 2080;     // hourly
  if (n < 25000) return n * 12;      // monthly
  return n;
};
allJobs = allJobs.filter(j => {
  const vals = [annual(j.salary_min), annual(j.salary_max)].filter(Boolean);
  if (!vals.length) return true;
  if (Math.max(...vals) >= SAL_FLOOR) return true;
  __srcStats.bad.push(`below $120k: "${j.title}" (${j.company})`);
  return false;
});

// ── Skip jobs where writing app code is the PRIMARY responsibility ────────────
const CODE_PRIMARY = [
  'building scalable web application','develop backend service',
  'full-stack development','experience with react is required',
  'ruby on rails','django framework','.net development','java spring boot',
  'mobile application development','design and develop software product',
  'software development lifecycle is your','you will write and maintain code',
];
allJobs = allJobs.filter(j => {
  const descTop = j.description.toLowerCase().substring(0, 1000);
  return !CODE_PRIMARY.some(kw => descTop.includes(kw));
});

// ── Defense contractor exclusions ─────────────────────────────────────────────
const DEFENSE = [
  'lockheed martin','raytheon','northrop grumman','booz allen',
  'general dynamics','l3harris','bae systems','leidos'
];
allJobs = allJobs.filter(j =>
  !DEFENSE.some(c => j.company.toLowerCase().includes(c))
);

// ── Repost aggregators, not employers ───────────────────────────────────
const AGGREGATORS = [
  'remote zest', 'flexboard', 'vacancy global', 'remote click',
  'remote quest', 'remote next', 'remotejobs', 'jobright',
];
allJobs = allJobs.filter(j =>
  !AGGREGATORS.some(a => (j.company || '').toLowerCase().includes(a))
);

// ── Title tier + skill overlap (2026-10-04) ─────────────────────────────
// Network Engineer is the primary target, Infrastructure Engineer secondary.
// Overlap is counted against the candidate's own stack (candidate_profile.md) - a
// network job that also asks for VMware/Proxmox/Docker/K8s is the sweet spot -
// and DevOps/SRE vocabulary counts against it.
const PRIMARY_T = /\bnetwork\b.*\b(engineer|architect|administrator|analyst|specialist)\b|\bfirewall engineer|\bwireless engineer|\bnoc engineer/;
const SECONDARY_T = /\binfrastructure\b.*\b(engineer|architect|administrator)\b|\binfrastructure operations|\bsystems? (engineer|administrator)|\bsysadmin|\bvirtualization|\bvmware|\bserver (engineer|administrator)|\bdata center engineer|\bcloud engineer|\bhybrid cloud/;
const SKILLS = {
  network:  ['bgp','ospf','mpls','dmvpn','vlan','qos','spanning tree','stp','multicast',
             'cisco','nexus','nx-os','ios-xe','juniper','junos','mist','aruba','meraki',
             'sd-wan','sdwan','routing','switching','wireless','wlc','dns','dhcp','ipam',
             'vpn','wan','lan','load balanc','f5'],
  security: ['palo alto','fortinet','fortigate','checkpoint','check point','asa',
             'firewall','intrusion prevention','ips','radius','zero trust','cloudflare',
             'pci','802.1x','nac','ise','segmentation'],
  systems:  ['vmware','vsphere','esxi','proxmox','hyper-v','virtualization','linux',
             'red hat','rhel','centos','windows server','active directory','docker',
             'kubernetes','k8s','container','backup','disaster recovery','azure','aws'],
  observability: ['solarwinds','orion','prometheus','grafana','splunk','elastic','syslog',
             'snmp','netflow','monitoring','loki','observability'],
  automation: ['ansible','python','n8n','automation','scripting','api'],
};
const DEVOPS_SIG = ['ci/cd','cicd','jenkins','github actions','gitlab ci','argocd','argo cd',
  'helm','slo','error budget','sre','site reliability','devops','microservices','golang',
  'rust','java','spring boot','software development','release engineering','build pipeline'];
for (const j of allJobs) {
  const t = j.title.toLowerCase();
  j.title_tier = PRIMARY_T.test(t) ? 'primary' : SECONDARY_T.test(t) ? 'secondary' : 'other';
  const txt = (j.title + ' ' + (j.description || '')).toLowerCase();
  const by = {};
  let hits = 0;
  for (const [cl, kws] of Object.entries(SKILLS)) {
    by[cl] = kws.filter(k => kwHit(txt, k)).length;
    hits += by[cl];
  }
  const dev = DEVOPS_SIG.filter(k => kwHit(txt, k)).length;
  // 12 distinct on-stack hits ~ a full match; each DevOps signal costs 8.
  j.skill_overlap = Math.max(0, Math.min(100, Math.round(hits * 100 / 12) - dev * 8));
  j.skill_clusters = Object.entries(by).filter(([, n]) => n).sort((a, b) => b[1] - a[1])
    .map(([cl, n]) => `${cl} ${n}`).join(', ') + (dev ? `; devops signals ${dev}` : '');
}

// ── Stable content key: same job from any board → same key ──────────────
const norm = s => (s || '').toLowerCase().replace(/[^a-z0-9]+/g, ' ').trim();
const dedupKey = j => `${norm(j.company)}::${norm(j.title)}`;

// Collapse duplicates WITHIN this run (same job pulled from several boards)
const seenThisRun = new Set();
allJobs = allJobs.filter(j => {
  const k = dedupKey(j);
  if (!k || k === '::' || seenThisRun.has(k)) return false;
  seenThisRun.add(k);
  return true;
});

// ── Dedup across runs via workflow static data ──────────────────────────
const sd = $getWorkflowStaticData('global');

// One-time bootstrap: seed from the 67 jobs already in Notion so the first
// run after this patch doesn't re-alert everything. Expires like any entry.
const SEED = [
  "actionet inc::network engineer level iii firewall",
